// ---------------------------------------------------------------------
// Ordre pédagogique du programme de conversation : du plus fondamental
// (bases sociales) au plus avancé (situations professionnelles complexes).
// L'utilisateur avance dans cet ordre, un scénario à la fois, et doit
// terminer un scénario pour débloquer le suivant.
// ---------------------------------------------------------------------
const SCENARIO_ORDER = [
  "meeting_someone",
  "small_talk",
  "directions",
  "restaurant",
  "supermarket",
  "shopping",
  "taxi",
  "pharmacy",
  "doctor",
  "airport",
  "hotel",
  "lost_item",
  "compliments",
  "phone_call",
  "job_interview",
  "meeting",
  "email_writing",
  "emergency_call",
  "free_talk",
];

// ---------------------------------------------------------------------
// Programme à 4 modules, débloqués dans l'ordre : Conjugaison → Conversation
// → (Traduction + Lecture débloqués ensemble).
// ---------------------------------------------------------------------
const SERIES_SIZE = 15; // nombre d'exercices dans une série
const CONJUGATION_SERIES_TARGET = 10; // séries à valider pour terminer Conjugaison
const TRANSLATION_SERIES_TARGET = 10; // séries à valider pour terminer Traduction

function isConversationDone(user) {
  const completed = new Set(user.completed_scenarios || []);
  return SCENARIO_ORDER.every((id) => completed.has(id));
}
function getProgramStatus(user) {
  // Le propriétaire de l'app a accès à tous les modules, sans avoir à suivre
  // la progression normale — utile pour tester et faire des modifications.
  const isOwner = !!user.is_owner;
  const conversationDone = isOwner || isConversationDone(user);
  return {
    conjugation: {
      unlocked: true,
      series_done: user.conjugation_series_done || 0,
      series_target: CONJUGATION_SERIES_TARGET,
      current_streak: user.conjugation_current_streak || 0,
      series_size: SERIES_SIZE,
      module_done: isOwner || !!user.conjugation_module_done,
    },
    conversation: {
      unlocked: isOwner || !!user.conjugation_module_done,
      module_done: conversationDone,
    },
    translation: {
      unlocked: conversationDone,
      series_done: user.translation_series_done || 0,
      series_target: TRANSLATION_SERIES_TARGET,
      current_streak: user.translation_current_streak || 0,
      series_size: SERIES_SIZE,
      module_done: isOwner || !!user.translation_module_done,
    },
    lecture: {
      unlocked: conversationDone,
    },
  };
}

