// ---------------------------------------------------------------------
// Recherche d'image (Pexels)
// ---------------------------------------------------------------------
app.get("/api/image", async (req, res) => {
  const rawQuery = (req.query.query || "").toString().slice(0, 100);
  if (!rawQuery) return res.status(400).json({ error: "Mot-clé manquant." });
  try {
    const key = (process.env.PEXELS_API_KEY || "").trim();
    const r = await fetch(
      "https://api.pexels.com/v1/search?query=" + encodeURIComponent(rawQuery) + "&per_page=10&orientation=landscape&size=large",
      { headers: { Authorization: key } }
    );
    const data = await r.json();
    if (!r.ok) {
      console.error("Erreur Pexels:", data);
      return res.status(502).json({ error: "Erreur du service d'images." });
    }
    // On garde la photo la plus fidèle à la scène décrite, en écartant
    // seulement celles dont la description Pexels indique une femme.
    const FEMALE_HINTS = ["woman", "women", "girl", "female", "lady", "ladies"];
    const photos = data.photos || [];
    const chosen =
      photos.find((p) => !FEMALE_HINTS.some((h) => (p.alt || "").toLowerCase().includes(h))) || photos[0];
    const url = chosen ? (chosen.src.large2x || chosen.src.large || chosen.src.original) : null;
    res.json({ url });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Impossible de contacter le service d'images." });
  }
});

// Renvoie l'état global du programme à 4 modules (déblocages, progression).
app.get("/api/program/status", authMiddleware, (req, res) => {
  res.json(getProgramStatus(req.user));
});

// Renvoie le scénario que l'utilisateur doit faire en ce moment, selon sa
// progression, ainsi que la liste des scénarios déjà terminés (pour la
// fonction "revoir un scénario précédent").
app.get("/api/scenario/current", authMiddleware, (req, res) => {
  if (!req.user.is_owner && !req.user.conjugation_module_done) {
    return res.status(403).json({ error: "Termine d'abord le module Conjugaison." });
  }
  const idx = Math.min(req.user.scenario_progress || 0, SCENARIO_ORDER.length - 1);
  const scenarioId = SCENARIO_ORDER[idx];
  const s = SCENARIOS[scenarioId];
  const completedList = (req.user.completed_scenarios || []).map((id) => ({
    id,
    label: SCENARIOS[id] ? SCENARIOS[id].label : id,
  }));
  const completedSet = new Set(req.user.completed_scenarios || []);
  // Liste complète des scénarios, dans l'ordre pédagogique, avec leur statut
  // (verrouillé / en cours / terminé) — pour que l'application les affiche
  // tous d'un coup, avec un cadenas sur ceux pas encore accessibles.
  const allScenarios = SCENARIO_ORDER.map((id, i) => {
    const sc = SCENARIOS[id];
    let status = "locked";
    if (completedSet.has(id)) status = "completed";
    else if (i === idx) status = "current";
    return { id, label: sc.label, category: sc.category, image_query: sc.image_query, status };
  });
  res.json({
    index: idx,
    total: SCENARIO_ORDER.length,
    scenario: { id: scenarioId, label: s.label, category: s.category, image_query: s.image_query },
    completed: completedList,
    all_scenarios: allScenarios,
    all_done: idx >= SCENARIO_ORDER.length - 1 && (req.user.completed_scenarios || []).includes(scenarioId),
  });
});

// Renvoie les détails d'un scénario précis, uniquement s'il fait partie des
// scénarios déjà terminés par l'utilisateur (pour la fonction "revoir").
app.get("/api/scenario/:id", authMiddleware, (req, res) => {
  if (!req.user.is_owner && !req.user.conjugation_module_done) {
    return res.status(403).json({ error: "Termine d'abord le module Conjugaison." });
  }
  const { id } = req.params;
  const s = SCENARIOS[id];
  if (!s) return res.status(404).json({ error: "Scénario introuvable." });
  const isCurrent = SCENARIO_ORDER[Math.min(req.user.scenario_progress || 0, SCENARIO_ORDER.length - 1)] === id;
  const isCompleted = (req.user.completed_scenarios || []).includes(id);
  if (!isCurrent && !isCompleted) {
    return res.status(403).json({ error: "Ce scénario n'est pas encore débloqué." });
  }
  res.json({ scenario: { id, label: s.label, category: s.category, image_query: s.image_query } });
});

// Marque le scénario en cours comme terminé et débloque le suivant.
app.post("/api/scenario/complete", authMiddleware, async (req, res) => {
  if (!req.user.is_owner && !req.user.conjugation_module_done) {
    return res.status(403).json({ error: "Termine d'abord le module Conjugaison." });
  }
  const idx = Math.min(req.user.scenario_progress || 0, SCENARIO_ORDER.length - 1);
  const scenarioId = SCENARIO_ORDER[idx];
  const completed = new Set(req.user.completed_scenarios || []);
  completed.add(scenarioId);
  const nextIdx = Math.min(idx + 1, SCENARIO_ORDER.length - 1);
  await User.findByIdAndUpdate(req.user.id, {
    completed_scenarios: Array.from(completed),
    scenario_progress: nextIdx,
  });
  const finished = idx >= SCENARIO_ORDER.length - 1;
  res.json({ ok: true, next_index: nextIdx, program_complete: finished });
});

// ---------------------------------------------------------------------
// Exercice de conjugaison — phrase à trous générée par l'IA.
// ---------------------------------------------------------------------
app.post("/api/conjugation/exercise", authMiddleware, async (req, res) => {
  const status = computeStatus(req.user);
  if (status.plan === "expired") {
    return res.status(403).json({ error: "Essai terminé, passe en Premium." });
  }
  const key = (process.env.GEMINI_API_KEY || "").trim();
  const TENSE_CYCLE = [
    "the present simple",
    "the past simple",
    "the future with 'will'",
  ];
  const TENSE_LABELS_FR = ["Présent", "Passé", "Futur"];
  const posInSeries = ((req.user.conjugation_current_streak || 0)) % TENSE_CYCLE.length;
  const forcedTense = TENSE_CYCLE[posInSeries];
  const tenseLabel = TENSE_LABELS_FR[posInSeries];
  const sys =
    "You generate English conjugation fill-in-the-blank exercises for a French-speaking beginner. " +
    "Pick ONE common, useful English verb (among the 300-500 most frequent everyday verbs — be, have, go, " +
    "do, make, take, want, need, know, think, say, get, come, see, give, find, tell, ask, work, feel, " +
    "become, leave, put, keep, begin, seem, help, talk, start, show, hear, play, run, move, live, believe, " +
    "bring, write, sit, stand, lose, pay, meet, learn, etc.). You MUST use this exact tense: " + forcedTense +
    ". Build ONE simple English sentence with a blank where the conjugated verb goes, with a clear time " +
    "marker in the sentence (e.g. 'Yesterday', 'Every day', 'Tomorrow'...). " +
    "Respond with ONLY a valid JSON object, no markdown, no code fences, matching exactly this shape: " +
    '{"sentence":"<the sentence with ___ for the blank>","options":["<4 choices, mixed order, including the correct one and 3 plausible wrong forms of the same verb>"],"answer":"<the exact correct choice, must match one of options>","translation":"<natural French translation of the full correct sentence>","explanation":"<one short sentence in French explaining why this tense/form is correct>","image_query":"<a vivid, detailed 8-12 word scene description in English for an AI image generator, describing the action/setting/mood of the sentence (e.g. \'a cheerful man drinking coffee by a sunny window in the morning\'); if a person appears in the scene, it must be a man, NEVER a woman; NEVER describe a specific person\'s body, appearance, or clothing in detail; focus on the activity, setting, colors, and atmosphere; keep it neutral and workplace-appropriate>"}';

  async function tryGenerate() {
    const body = {
      contents: [{ role: "user", parts: [{ text: "Generate a new exercise." }] }],
      generationConfig: { maxOutputTokens: 800, temperature: 1, responseMimeType: "application/json" },
      systemInstruction: { parts: [{ text: sys }] },
    };
    const r = await fetchGeminiWithRetry(body, key);
    const data = r.data;
    if (!r.ok) {
      console.error("Erreur Gemini (conjugation):", JSON.stringify(data));
      const detail = (data && data.error && data.error.message) ? data.error.message : JSON.stringify(data);
      return { error: "IA : " + detail };
    }
    const parts = (data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts) || [];
    const raw = parts.map((p) => p.text || "").filter(Boolean).join("");
    let parsed;
    try {
      const jsonMatch = raw.match(/\{[\s\S]*\}/);
      parsed = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
    } catch (e) {
      console.error("Réponse IA (conjugaison) non-JSON :", raw);
      return { error: "L'IA n'a pas répondu dans le bon format, réessaie." };
    }
    const { sentence, options, answer, translation, explanation, image_query } = parsed || {};
    if (!sentence || !answer || !Array.isArray(options) || options.length < 2) {
      console.error("Réponse IA (conjugaison) incomplète :", raw);
      return { error: "L'IA a donné une réponse incomplète, réessaie." };
    }
    return {
      sentence: String(sentence).trim(),
      options: options.map((o) => String(o).trim()).filter(Boolean),
      answer: String(answer).trim(),
      translation: String(translation || "").trim(),
      explanation: String(explanation || "").trim(),
      image_query: String(image_query || "").trim(),
      tense_label: tenseLabel,
    };
  }

  try {
    let result = await tryGenerate();
    if (result && result.error) result = await tryGenerate();
    if (!result || result.error) {
      return res.status(502).json({ error: (result && result.error) || "Réponse de l'IA incomplète, réessaie." });
    }
    res.json(result);
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Impossible de générer l'exercice pour le moment." });
  }
});

// Enregistre qu'un exercice de conjugaison vient d'être fait (peu importe si
// juste ou faux — seule la pratique compte pour avancer dans les séries).
app.post("/api/conjugation/record", authMiddleware, async (req, res) => {
  let streak = (req.user.conjugation_current_streak || 0) + 1;
  let seriesDone = req.user.conjugation_series_done || 0;
  let moduleDone = !!req.user.conjugation_module_done;
  let seriesJustCompleted = false;
  if (streak >= SERIES_SIZE) {
    streak = 0;
    seriesDone += 1;
    seriesJustCompleted = true;
    if (seriesDone >= CONJUGATION_SERIES_TARGET) moduleDone = true;
  }
  await User.findByIdAndUpdate(req.user.id, {
    conjugation_current_streak: streak,
    conjugation_series_done: seriesDone,
    conjugation_module_done: moduleDone,
  });
  res.json({
    current_streak: streak,
    series_done: seriesDone,
    series_target: CONJUGATION_SERIES_TARGET,
    series_size: SERIES_SIZE,
    series_just_completed: seriesJustCompleted,
    module_done: moduleDone,
  });
});

// ---------------------------------------------------------------------
// Module Traduction — bidirectionnel FR ↔ EN.
// ---------------------------------------------------------------------
app.post("/api/translation/exercise", authMiddleware, async (req, res) => {
  if (!req.user.is_owner && !isConversationDone(req.user)) {
    return res.status(403).json({ error: "Termine d'abord le module Conversation." });
  }
  const status = computeStatus(req.user);
  if (status.plan === "expired") {
    return res.status(403).json({ error: "Essai terminé, passe en Premium." });
  }
  const key = (process.env.GEMINI_API_KEY || "").trim();
  const fromFrench = Math.random() < 0.5;
  const sys = fromFrench
    ? "Generate one short, simple sentence in FRENCH (beginner to intermediate level, everyday life topic), " +
      'then its natural English translation. Respond with ONLY a valid JSON object, no markdown, matching ' +
      'exactly this shape: {"prompt":"<the French sentence>","answer":"<the English translation>"}'
    : "Generate one short, simple sentence in ENGLISH (beginner to intermediate level, everyday life topic), " +
      'then its natural French translation. Respond with ONLY a valid JSON object, no markdown, matching ' +
      'exactly this shape: {"prompt":"<the English sentence>","answer":"<the French translation>"}';
  async function tryGenerate() {
    const body = {
      contents: [{ role: "user", parts: [{ text: "Generate a new sentence." }] }],
      generationConfig: { maxOutputTokens: 400, temperature: 1, responseMimeType: "application/json" },
      systemInstruction: { parts: [{ text: sys }] },
    };
    const r = await fetchGeminiWithRetry(body, key);
    const data = r.data;
    if (!r.ok) {
      console.error("Erreur Gemini (translation):", JSON.stringify(data));
      return null;
    }
    const parts = (data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts) || [];
    const raw = parts.map((p) => p.text || "").filter(Boolean).join("");
    let parsed;
    try {
      const jsonMatch = raw.match(/\{[\s\S]*\}/);
      parsed = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
    } catch (e) {
      console.error("Réponse IA (traduction) non-JSON :", raw);
      return null;
    }
    const { prompt, answer } = parsed || {};
    if (!prompt || !answer) {
      console.error("Réponse IA (traduction) incomplète :", raw);
      return null;
    }
    return { prompt: String(prompt).trim(), lang: fromFrench ? "fr" : "en", answer: String(answer).trim() };
  }
  try {
    let result = await tryGenerate();
    if (!result) result = await tryGenerate();
    if (!result) {
      return res.status(502).json({ error: "Réponse de l'IA incomplète, réessaie." });
    }
    res.json(result);
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Impossible de générer l'exercice pour le moment." });
  }
});

