app.get("/api/lecture/text/:id", authMiddleware, async (req, res) => {
  const status = computeStatus(req.user);
  if (status.plan === "expired") {
    return res.status(403).json({ error: "Essai terminé, passe en Premium." });
  }
  const id = parseInt(req.params.id, 10);
  const t = LECTURE_TEXTS.find((x) => x.id === id);
  if (!t) return res.status(404).json({ error: "Texte introuvable." });
  const unlockedUpTo = req.user.is_owner ? LECTURE_TEXTS.length : (req.user.lecture_unlocked_up_to || 1);
  if (id > unlockedUpTo) {
    return res.status(403).json({ error: "Ce texte n'est pas encore débloqué — lis d'abord le précédent à voix haute." });
  }
  const readIds = new Set(req.user.lecture_read_ids || []);
  if (!readIds.has(id)) {
    readIds.add(id);
    await User.findByIdAndUpdate(req.user.id, { lecture_read_ids: Array.from(readIds) });
  }
  res.json(t);
});

// Vérifie la lecture à voix haute d'un texte (le navigateur transcrit ce
// que la personne a dit, et envoie ce texte ici pour comparaison). Si le
// score est suffisant, débloque le texte suivant.
app.post("/api/lecture/verify-reading", authMiddleware, async (req, res) => {
  const { id, transcript } = req.body || {};
  const textId = parseInt(id, 10);
  const t = LECTURE_TEXTS.find((x) => x.id === textId);
  if (!t) return res.status(404).json({ error: "Texte introuvable." });

  const normalize = (s) =>
    (s || "")
      .toLowerCase()
      .replace(/[^a-z\s']/g, " ")
      .split(/\s+/)
      .filter(Boolean);
  const targetWords = normalize(t.text);
  const saidWords = new Set(normalize(transcript));
  const results = targetWords.map((w) => ({ word: w, ok: saidWords.has(w) }));
  const correctCount = results.filter((r) => r.ok).length;
  const accuracy = targetWords.length ? correctCount / targetWords.length : 0;
  const passed = accuracy >= 0.7;

  let unlockedUpTo = req.user.lecture_unlocked_up_to || 1;
  let justUnlocked = false;
  if (passed && textId === unlockedUpTo && unlockedUpTo < LECTURE_TEXTS.length) {
    unlockedUpTo += 1;
    justUnlocked = true;
    await User.findByIdAndUpdate(req.user.id, { lecture_unlocked_up_to: unlockedUpTo });
  }

  res.json({
    passed,
    accuracy: Math.round(accuracy * 100),
    results,
    unlocked_up_to: unlockedUpTo,
    just_unlocked_next: justUnlocked,
  });
});

app.post("/api/ai", authMiddleware, async (req, res) => {
  const status = computeStatus(req.user);
  if (status.plan === "expired") {
    return res.status(403).json({ error: "Essai terminé, passe en Premium." });
  }
  const { messages, system, scenario, phase } = req.body || {};
  if (!Array.isArray(messages) || !messages.length) {
    return res.status(400).json({ error: "Message manquant." });
  }
  try {
    const key = (process.env.GEMINI_API_KEY || "").trim();
    const contents = messages.map((m) => ({
      role: m.role === "assistant" ? "model" : "user",
      parts: [{ text: m.content }],
    }));
    const body = { contents, generationConfig: { maxOutputTokens: 2000 } };
    // Si un scénario est fourni (ex: "airport"), ses instructions priment ;
    // sinon on utilise le "system" générique envoyé par l'app, si présent.
    const scenarioConfig = scenario && SCENARIOS[scenario];
    let finalSystem = scenarioConfig ? scenarioConfig.system : system;
    // Discussion libre : pas de scénario précis et pas de "system" fourni
    // par l'app → on applique une consigne par défaut qui pousse la
    // personne à parler et corrige gentiment ses erreurs.
    if (!scenarioConfig && !system) {
      finalSystem =
        "You are a friendly, patient English conversation partner helping a French-speaking beginner practice " +
        "speaking. Keep the conversation going with simple, engaging follow-up questions on everyday topics. " +
        "When the user makes a mistake, gently point it out and correct it in English, then continue the " +
        "conversation naturally. Keep your responses short (2 to 4 sentences).";
    }
    // Phase "intro" : l'IA présente d'abord un dialogue MODÈLE complet,
    // joué entre deux personnages (IA contre IA), du début à la fin de la
    // situation — l'apprenant regarde et écoute, il ne parle pas encore.
    // Phase normale : l'IA vérifie la compréhension avec un petit exercice,
    // corrige, puis peut proposer un nouvel extrait ou exercice.
    if (scenarioConfig && phase === "intro") {
      finalSystem =
        "You are a friendly English teacher for a French-speaking beginner. Write ONE complete example " +
        "dialogue demonstrating this real-life situation, played entirely by you between two characters, " +
        "from the very beginning (how the conversation starts) to the natural end (how it closes/says " +
        "goodbye). 6 to 10 short lines total, simple English, alternating naturally between the two " +
        "characters. The user is only watching/listening to this model dialogue, not participating in it. " +
        "After the dialogue, write ONE simple comprehension exercise in French asking the user something " +
        "about it (e.g. what to say to start the conversation, or how to respond in a given moment).\n\n" +
        "Situation: " + scenarioConfig.system + "\n\n" +
        'Respond with ONLY a valid JSON object, no markdown, no code fences, matching exactly this shape: ' +
        '{"dialogue":[{"speaker":"A","en":"<line in English>","fr":"<French translation>"}, ...],"exercise":"<the comprehension exercise, in French>"}';
      body.generationConfig.responseMimeType = "application/json";
    } else if (scenarioConfig) {
      finalSystem =
        "You are a friendly English teacher for a French-speaking beginner, continuing a lesson about this " +
        "real-life situation: " + scenarioConfig.system.replace(/^You are an?[^.]*\.\s*/i, "") + "\n\n" +
        "The user just answered your exercise question. Check their answer: say clearly if it's correct, " +
        "gently correct any mistake in English with French in parentheses, and briefly explain why if useful. " +
        "Then either show one more short model exchange (2-3 lines, 'Person A:'/'Person B:' with French " +
        "translations) from later in the situation, or give one more small comprehension exercise — vary it. " +
        "Keep messages short (3-5 lines). This stays a guided lesson with model dialogue and exercises, never " +
        "an open-ended roleplay conversation with the user pretending to be in the situation themselves.";
    }
    if (finalSystem) body.systemInstruction = { parts: [{ text: finalSystem }] };

    const r = await fetchGeminiWithRetry(body, key);
    const data = r.data;
    if (!r.ok) {
      console.error("Erreur Gemini:", data);
      const detail = (data && data.error && data.error.message) ? data.error.message : JSON.stringify(data);
      return res.status(502).json({ error: "IA: " + detail });
    }
    const parts = (data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts) || [];
    const text = parts.map((p) => p.text || "").filter(Boolean).join("\n");
    res.json({ text });
  } catch (e) {
    console.error(e);
    res.status(500).json({ error: "Impossible de contacter l'IA pour le moment." });
  }
});

