// ---------------------------------------------------------------------
// Webhook d'approbation automatique — appelé par une automatisation sur
// le téléphone (ex: MacroDroid) dès qu'un SMS Orange Money arrive.
// ---------------------------------------------------------------------
function normalizePhone(p) {
  return String(p || "").replace(/\D/g, "").slice(-8);
}
app.get("/api/webhook/orange-payment", (req, res) => {
  handleOrangePaymentWebhook(req.query, res);
});
app.post("/api/webhook/orange-payment", (req, res) => {
  handleOrangePaymentWebhook(req.body || {}, res);
});
async function handleOrangePaymentWebhook(input, res) {
  const { secret, message } = input;
  if (!secret || secret !== process.env.AUTO_APPROVE_SECRET) {
    return res.status(403).json({ error: "Secret invalide." });
  }
  if (!message) {
    return res.status(400).json({ error: "Message manquant." });
  }
  const amountMatch = message.match(/reçu\s+([\d.,]+)\s*Fcfa/i);
  const phoneMatch = message.match(/du\s+([\d\s]{6,})\s*,/i);
  if (!amountMatch || !phoneMatch) {
    return res.status(400).json({ error: "Impossible de lire le montant ou le numéro dans ce message." });
  }
  const amount = parseFloat(amountMatch[1].replace(",", "."));
  const target = normalizePhone(phoneMatch[1]);
  const pending = await db.listPendingManualPayments();
  const user = pending.find((u) => normalizePhone(u.phone) === target);
  if (!user) {
    return res.status(404).json({ error: "Aucun paiement en attente pour ce numéro." });
  }
  const plan = PLANS[user.pending_plan] || PLANS.biweekly;
  if (amount < plan.amount) {
    return res.status(400).json({ error: "Montant reçu insuffisant pour le forfait demandé." });
  }
  const newUntil = Date.now() + plan.days * DAY_MS;
  await db.setPremium(user.id, newUntil);
  res.json({ ok: true, phone: user.phone, plan: plan.label });
}

