// ---------------------------------------------------------------------
// Appelle l'API Gemini avec de nouvelles tentatives automatiques si le
// modèle est temporairement surchargé (erreur "high demand"/503) — pour
// que ce genre de souci passager, côté Google, passe inaperçu pour
// l'utilisateur la plupart du temps.
// ---------------------------------------------------------------------
async function fetchGeminiWithRetry(body, key, retries = 2) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    const r = await fetch(
      "https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent?key=" + key,
      { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }
    );
    const data = await r.json();
    const overloaded =
      !r.ok &&
      ((data && data.error && /overload|high demand|unavailable/i.test(data.error.message || "")) || r.status === 503);
    if (r.ok || !overloaded || attempt === retries) {
      return { ok: r.ok, status: r.status, data };
    }
    await new Promise((resolve) => setTimeout(resolve, 1200 * (attempt + 1)));
  }
}

